<!doctype html><html><head><meta charset="utf-8"><title>{{$invoice->invoice_number}}</title><style>@page{size:A4;margin:14mm}body{font:13px Arial;color:#222}.head{display:flex;justify-content:space-between;border-bottom:2px solid #222;padding-bottom:15px}.two{display:flex;justify-content:space-between;margin:25px 0}.two>div{width:48%}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}th{background:#f5f5f5}.total{margin-left:auto;width:320px}.total div{display:flex;justify-content:space-between;padding:5px}.grand{font-size:17px;font-weight:bold;border-top:2px solid #222}.muted{color:#666}@media print{.no-print{display:none}}</style></head><body><div class="head"><div><h1>JALVAN</h1><div>Tax Invoice</div></div><div><b>{{$invoice->invoice_number}}</b><br>Date: {{$invoice->invoice_date?->format('d M Y')}}</div></div><div class="two"><div><b>Bill To</b><p>{{$invoice->billing_name}}<br>{{$invoice->billing_address}}<br>{{$invoice->billing_city}}, {{$invoice->billing_state}} {{$invoice->billing_pincode}}<br>{{$invoice->billing_gstin}}</p></div><div><b>Payment</b><p>Status: {{$invoice->payment_status}}<br>Due: {{$invoice->due_date?->format('d M Y')??'—'}}</p></div></div><table><thead><tr><th>Description</th><th>Qty</th><th>Unit Price</th><th>Tax</th><th>Total</th></tr></thead><tbody>@foreach($invoice->items as $x)<tr><td>{{$x->description}}</td><td>{{$x->quantity}}</td><td>₹{{number_format($x->unit_price,2)}}</td><td>₹{{number_format($x->tax_amount,2)}}</td><td>₹{{number_format($x->total,2)}}</td></tr>@endforeach</tbody></table><div class="total"><div>Subtotal <span>₹{{number_format($invoice->subtotal,2)}}</span></div><div>Discount <span>₹{{number_format($invoice->discount,2)}}</span></div><div>Tax <span>₹{{number_format($invoice->tax_amount,2)}}</span></div><div>Shipping <span>₹{{number_format($invoice->shipping_amount,2)}}</span></div><div>Other <span>₹{{number_format($invoice->other_charges,2)}}</span></div><div class="grand">Grand Total <span>₹{{number_format($invoice->grand_total,2)}}</span></div><div>Paid <span>₹{{number_format($invoice->paid_amount,2)}}</span></div><div>Outstanding <span>₹{{number_format($invoice->outstanding_amount,2)}}</span></div></div><p class="muted">{{$invoice->terms}}</p><script>window.onload=()=>window.print()</script></body></html>
